INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein DIMM dasselbe wie ein SIMM?', 2, '[{"text": "Nein", "correct": true, "because": "DIMM hat 64-Bit, SIMM 32-Bit"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Datenwege"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat ein DIMM im PC?', 3, '[{"text": "Arbeitsspeicher bereitstellen", "correct": true, "because": "RAM für CPU"}, {"text": "Daten dauerhaft speichern", "correct": false, "because": "Nicht Festplatte"}, {"text": "Prozessorleistung erhöhen", "correct": false, "because": "Nur Speicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein DIMM?', 5, '[{"text": "64-Bit-Datenweg", "correct": true, "because": "Schneller als SIMM"}, {"text": "Doppelte Kontakte", "correct": true, "because": "Beidseitig genutzt"}, {"text": "32-Bit-Bus", "correct": false, "because": "SIMM-Eigenschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIMM ist flüchtig. b) Es ist abwärtskompatibel mit SIMM.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht kompatibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines DIMM?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Muss zum Mainboard passen"}, {"text": "Taktfrequenz", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein DIMM auch in Laptops läuft?', 2, '[{"text": "Ja", "correct": true, "because": "Als SO-DIMM"}, {"text": "Nein", "correct": false, "because": "Nicht nur Desktop"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche DIMM-Variante ist für Server typisch?', 3, '[{"text": "RDIMM", "correct": true, "because": "Stabilität für Server"}, {"text": "UDIMM", "correct": false, "because": "Für Desktop"}, {"text": "SO-DIMM", "correct": false, "because": "Für Laptops"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen DIMM effizient?', 5, '[{"text": "64-Bit-Datenweg", "correct": true, "because": "Schnelle Übertragung"}, {"text": "ECC-Unterstützung", "correct": true, "because": "Fehlerkorrektur"}, {"text": "32-Bit-Breite", "correct": false, "because": "SIMM-Eigenschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DIMM hat doppelte Kontakte. b) Es ist immer schneller als SSD. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSD ist Speicher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein DIMM?', 4, '[{"text": "Mainboard-Steckplatz", "correct": false, "because": "Notwendig"}, {"text": "RAM-Chips", "correct": false, "because": "Kernkomponente"}, {"text": "Externe Festplatte", "correct": true, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DDR5-DIMM mit DDR4 kompatibel?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Pins"}, {"text": "Ja", "correct": false, "because": "Nicht kompatibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen von DIMM gibt es?', 4, '[{"text": "UDIMM", "correct": true, "because": "Ungepuffert"}, {"text": "SO-DIMM", "correct": true, "because": "Kleinformat"}, {"text": "SIMM", "correct": false, "because": "Vorgänger"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DIMM nur für Gaming ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Server und Büro"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem DIMM-Kauf?', 3, '[{"text": "Mainboard-Kompatibilität", "correct": true, "because": "Muss passen"}, {"text": "Markenlogo", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Kein Leistungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIMM hat 288 Pins bei DDR4. b) Es ist nicht flüchtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flüchtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein DIMM?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "64-Bit-Datenweg"}, {"text": "Einfacher Austausch", "correct": true, "because": "Modular"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Flüchtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem DIMM unwichtig?', 3, '[{"text": "Taktfrequenz", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Kapazität", "correct": false, "because": "Wichtig für Nutzung"}, {"text": "Gewicht", "correct": true, "because": "Kaum relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht ein DIMM eine eigene Stromversorgung?', 3, '[{"text": "Nein", "correct": true, "because": "Via Mainboard"}, {"text": "Ja", "correct": false, "because": "Kein separates Netzteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DIMM nur für Desktops ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Laptops und Server"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht DIMM flexibel?', 4, '[{"text": "Modularität", "correct": true, "because": "Einfach austauschbar"}, {"text": "Feste Kapazität", "correct": false, "because": "Variabel"}, {"text": "Hohe Spannung", "correct": false, "because": "Nicht primär"}]');
